class Solution:
    def minAcquisitionCost(self, individual: list[int], bundle_cost: int) -> int:
        return min(sum(individual), bundle_cost)

#include <vector>
#include <numeric>
#include <algorithm>
using namespace std;

class Solution {
public:
    int minAcquisitionCost(vector<int>& individual, int bundle_cost) {
        int sum = 0;
        for (int x : individual) sum += x;
        return min(sum, bundle_cost);
    }
};

class Solution {
    public int minAcquisitionCost(int[] individual, int bundleCost) {
        int sum = 0;
        for (int x : individual) sum += x;
        return Math.min(sum, bundleCost);
    }
}

var minAcquisitionCost = function(individual, bundle_cost) {
    const sum = individual.reduce((a, b) => a + b, 0);
    return Math.min(sum, bundle_cost);
};
